import{_ as n,C as r,o as i,c as s,j as e,a as d,E as o,a5 as a}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"树选择","description":"","frontmatter":{},"headers":[],"relativePath":"components/tree-select.md","filePath":"components/tree-select.md","lastUpdated":1787365442000}'),h={name:"components/tree-select.md"},p={id:"树选择",tabindex:"-1"};function g(b,t,u,x,m,T){const l=r("Badge"),c=r("XhDemo");return i(),s("div",null,[e("h1",p,[t[0]||(t[0]=d("树选择 ",-1)),o(l,{type:"info",text:"tree-select"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#树选择","aria-label":'Permalink to "树选择 <Badge type="info" text="tree-select" />"'},"​",-1))]),t[3]||(t[3]=a('<p>浮层里放一棵树的选择器：层级不规整、深浅不一时用它。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>选项是任意形状的树（组织架构、目录、权限节点）。</li><li>需要在浮层里展开、勾选，并把选中项回显在触发器上。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>层级规整、层数固定：<a href="./cascader">级联选择</a>的分列展开更快。</li><li>树本身就是页面主体：用<a href="./tree">树</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>选中与展开两套值各自可受控。</li><li><code>cascade</code> 与 <code>checkedStrategy</code> 决定勾选是否带子级、回显给哪一层。</li><li>支持只挑叶子不挑分支、浮层内关键词过滤、子节点异步加载。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>收起时整个控件只占触发器一个 Tab 位，展开那一刻焦点真的进树、落在已选中的那行上</p>',10)),o(c,{src:"tree-select/01-basic"}),t[4]||(t[4]=e("h3",{id:"选中与展开双受控",tabindex:"-1"},[d("选中与展开双受控 "),e("a",{class:"header-anchor",href:"#选中与展开双受控","aria-label":'Permalink to "选中与展开双受控"'},"​")],-1)),t[5]||(t[5]=e("p",null,"两份集合都由宿主持有：组件只发事件，宿主写回它才动，回显的就是写回的那两份",-1)),o(c,{src:"tree-select/02-controlled"}),t[6]||(t[6]=e("h3",{id:"多选与表单",tabindex:"-1"},[d("多选与表单 "),e("a",{class:"header-anchor",href:"#多选与表单","aria-label":'Permalink to "多选与表单"'},"​")],-1)),t[7]||(t[7]=e("p",null,"multiple 下确认键是切换、浮层不收起；写了 hidden-input 才随表单提交，多个值按逗号拼成一串",-1)),o(c,{src:"tree-select/03-multiple"}),t[8]||(t[8]=e("h3",{id:"形态",tabindex:"-1"},[d("形态 "),e("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[9]||(t[9]=e("p",null,"variant 只换触发框的描边与底色，浮层与树的长相不跟着变",-1)),o(c,{src:"tree-select/04-variant"}),t[10]||(t[10]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=e("p",null,"tone 决定用哪族颜色，与 variant 正交，这里统一用 subtle 形态",-1)),o(c,{src:"tree-select/05-tone"}),t[12]||(t[12]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=e("p",null,"size 换掉行高、内边距与字号，不写就是缺省档",-1)),o(c,{src:"tree-select/06-size"}),t[14]||(t[14]=e("h3",{id:"禁用、只读与校验失败",tabindex:"-1"},[d("禁用、只读与校验失败 "),e("a",{class:"header-anchor",href:"#禁用、只读与校验失败","aria-label":'Permalink to "禁用、只读与校验失败"'},"​")],-1)),t[15]||(t[15]=e("p",null,"disabled 连键盘入口都没有；readOnly 照常展开浏览但值改不动也清不掉；invalid 只报校验态，交互一切照旧",-1)),o(c,{src:"tree-select/07-state"}),t[16]||(t[16]=e("h3",{id:"异步加载子节点",tabindex:"-1"},[d("异步加载子节点 "),e("a",{class:"header-anchor",href:"#异步加载子节点","aria-label":'Permalink to "异步加载子节点"'},"​")],-1)),t[17]||(t[17]=e("p",null,"展开某个分支才去要它的子节点：先摆一行禁用占位，数据回来就地换掉，显示文本随之取到新 label",-1)),o(c,{src:"tree-select/08-async"}),t[18]||(t[18]=e("h3",{id:"浮层里的操作区",tabindex:"-1"},[d("浮层里的操作区 "),e("a",{class:"header-anchor",href:"#浮层里的操作区","aria-label":'Permalink to "浮层里的操作区"'},"​")],-1)),t[19]||(t[19]=e("p",null,"content 里除了树还能放别的：在浮层内点按钮不算点在外面，浮层不会因此收起",-1)),o(c,{src:"tree-select/09-action"}),t[20]||(t[20]=e("h3",{id:"级联勾选与回显策略",tabindex:"-1"},[d("级联勾选与回显策略 "),e("a",{class:"header-anchor",href:"#级联勾选与回显策略","aria-label":'Permalink to "级联勾选与回显策略"'},"​")],-1)),t[21]||(t[21]=e("p",null,"multiple 加 cascade 内建父子传导：点分支整枝勾上、子全勾父勾、部分勾中半选；对外值按 checked-strategy 收敛，parent 档整组选满只报组名",-1)),o(c,{src:"tree-select/10-checkable"}),t[22]||(t[22]=e("h3",{id:"浮层内关键词过滤",tabindex:"-1"},[d("浮层内关键词过滤 "),e("a",{class:"header-anchor",href:"#浮层内关键词过滤","aria-label":'Permalink to "浮层内关键词过滤"'},"​")],-1)),t[23]||(t[23]=e("p",null,"输入框是树的兄弟节点，树的键盘处理器挂在 tree 上，打字不会被连打检索收走；换掉 collection 可见行与方向键顺序跟着重算",-1)),o(c,{src:"tree-select/11-filter"}),t[24]||(t[24]=e("h3",{id:"只挑文件不挑目录",tabindex:"-1"},[d("只挑文件不挑目录 "),e("a",{class:"header-anchor",href:"#只挑文件不挑目录","aria-label":'Permalink to "只挑文件不挑目录"'},"​")],-1)),t[25]||(t[25]=e("p",null,"选中值与展开态双受控：目录的值不写回，紧跟着那一次收起意图也一并吞掉，点目录就只剩展开收起",-1)),o(c,{src:"tree-select/12-file-picker"}),t[26]||(t[26]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tree-select&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTreeSelectBranch</code> <code>XhTreeSelectBranchContent</code> <code>XhTreeSelectBranchControl</code> <code>XhTreeSelectBranchIndicator</code> <code>XhTreeSelectBranchText</code> <code>XhTreeSelectBranchTrigger</code> <code>XhTreeSelectClearTrigger</code> <code>XhTreeSelectContent</code> <code>XhTreeSelectHiddenInput</code> <code>XhTreeSelectIndicator</code> <code>XhTreeSelectItem</code> <code>XhTreeSelectItemIndicator</code> <code>XhTreeSelectItemText</code> <code>XhTreeSelectLabel</code> <code>XhTreeSelectPositioner</code> <code>XhTreeSelectRoot</code> <code>XhTreeSelectTree</code> <code>XhTreeSelectTrigger</code> <code>XhTreeSelectValueText</code></td></tr><tr><td>组合式函数</td><td><code>useTreeSelect</code></td></tr><tr><td>状态机</td><td><code>treeSelectMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tree-select.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tree-select&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>trigger</code></strong> · <code>value-text</code> · <code>indicator</code> · <code>clear-trigger</code> · <code>positioner</code> · <strong><code>content</code></strong> · <strong><code>tree</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>item-indicator</code> · <code>branch</code> · <code>branch-control</code> · <code>branch-trigger</code> · <code>branch-indicator</code> · <code>branch-text</code> · <code>branch-content</code> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>TreeNode[]</code></td><td></td><td>树数据，层级元信息与显示文本的唯一事实源。缺省为空树。</td></tr><tr><td><code>value</code></td><td><code>string | string[]</code></td><td></td><td>选中值。给定即受控：cell 直读 prop，写只发 onValueChange 不落内部值。 单选写成裸串是简写，内部一律归一成数组。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | string[]</code></td><td></td><td></td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td><td>展开集合。给定即受控，语义同上。</td></tr><tr><td><code>defaultExpandedValue</code></td><td><code>string[]</code></td><td></td><td></td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td>展开态。给定即受控：内部不再自改，只发 onOpenChange。</td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td><td>多选：选中是集合，选中后浮层不收起、焦点留在树里以便接着挑。</td></tr><tr><td><code>cascade</code></td><td><code>boolean</code></td><td></td><td>多选下父子级联勾选：点分支整枝传导、子全勾父勾、部分勾中半选， 禁用子树整棵冻结。默认 false（朴素切换）；单选下无效。</td></tr><tr><td><code>checkedStrategy</code></td><td><code>CascadeStrategy</code></td><td></td><td>级联下对外值的收敛策略，默认 child（只收叶）；parent = 最高整枝，all = 全部勾中节点。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整个控件禁用：trigger 用原生 disabled，表单出口不参与提交。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：浮层照常展开、树照常浏览与展开收起，但选中值改不动、也清不掉。 disabled 则连键盘入口都没有。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：trigger 报 aria-invalid，各角色节点带 data-invalid。</td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline / subtle / ghost，决定触发框的描边与底色怎么用。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定聚焦与选中用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定触发框与树节点行的几何档位。</td></tr><tr><td><code>placeholder</code></td><td><code>string</code></td><td></td><td>无选中时 value-text 显示的占位文字。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TreeSelectTranslations&gt;</code></td><td></td><td>读屏用的文案，默认英文。</td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td></td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>上下键走到首尾是否回绕，默认 false。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只对调左右方向键的「展开/收起」语义。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。给定后表单出口才带 name，选中值随表单一并提交。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: TreeSelectValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onExpandedChange</code></td><td><code>(details: TreeSelectExpandedChangeDetails) =&gt; void</code></td><td></td><td>展开集合变化意图回调；语义同上。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: TreeSelectOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>TreeSelectValueChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>expanded-change</code></td><td><code>TreeSelectExpandedChangeDetails</code></td><td>展开集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>open-change</code></td><td><code>TreeSelectOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTreeSelectRoot</code></td><td><code>default</code></td><td><code>TreeSelectRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>tree</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>TOGGLE</code> · <code>CLOSE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code> · <code>NODE.FOCUS</code> · <code>NODE.LOST</code> · <code>NODE.SELECT</code> · <code>VALUE.SET</code> · <code>VALUE.CLEAR</code> · <code>EXPANDED.SET</code> · <code>BRANCH.EXPAND</code> · <code>BRANCH.COLLAPSE</code> · <code>BRANCH.TOGGLE</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isMultiple</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTreeSelect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly TreeNode[]</code></td><td>作者给的原始树数据。</td></tr><tr><td><code>visibleNodes</code></td><td><code>readonly TreeVisibleNode[]</code></td><td>当前可见行序列（收起分支的子树不在其中）。 方向键、Home/End 与连打检索都在它上面走，不是在原始树上走。</td></tr><tr><td><code>value</code></td><td><code>string[]</code></td><td>选中集合；单选下长度 ≤ 1，形状不随模式变。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>valueText</code></td><td><code>string | null</code></td><td>选中项的显示文本（多选用逗号加空格连接）；无选中时为 null。取自 collection 的 label。</td></tr><tr><td><code>displayText</code></td><td><code>string</code></td><td>value-text 实际显示的文字：有选中取其文本，否则取 placeholder。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；收起、或它已被收起而不可见时为 null。</td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>canClear</code></td><td><code>boolean</code></td><td>清空按钮此刻可不可按。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isIndeterminate</code></td><td><code>(value: string) =&gt; boolean</code></td><td>级联模式下该分支是否半选（有效叶后代有勾有不勾）；非级联恒 false。</td></tr><tr><td><code>isExpanded</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>setExpandedValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>expand</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>collapse</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td>单选替换、多选切换，与点节点同一语义。</td></tr><tr><td><code>clear</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getValueTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getClearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTreeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchControlProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTriggerProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchIndicatorProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTextProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchContentProps</code></td><td><code>(props: TreeSelectNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单出口：一份 type=hidden 的原生 input，选中值按逗号拼成一串随表单提交。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/combobox/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>closed, focus in trigger</td><td>展开浮层并把焦点落到选中节点（无选中或它藏在收起的分支里则落首个可用行）</td></tr><tr><td><code>ArrowDown</code></td><td>closed, focus in trigger</td><td>展开浮层并把焦点落到选中节点的下一个可用行</td></tr><tr><td><code>ArrowUp</code></td><td>closed, focus in trigger</td><td>展开浮层并把焦点落到选中节点的上一个可用行</td></tr><tr><td><code>Delete</code></td><td>focus in trigger, 有值且未禁用/只读</td><td>清空全部选中值，焦点留在 trigger</td></tr><tr><td><code>Backspace</code></td><td>focus in trigger, 有值且未禁用/只读</td><td>单选清空；多选去掉最后一个选中值</td></tr><tr><td><code>ArrowDown</code></td><td>open, focus in content</td><td>焦点移到下一个可见行（禁用行跳过；loop 默认关，末行不回绕）</td></tr><tr><td><code>ArrowUp</code></td><td>open, focus in content</td><td>焦点移到上一个可见行（禁用行跳过；loop 默认关，首行不回绕）</td></tr><tr><td><code>Home</code></td><td>open, focus in content</td><td>焦点移到首个可见行</td></tr><tr><td><code>End</code></td><td>open, focus in content</td><td>焦点移到末个可见行（展开着的子树也算行）</td></tr><tr><td><code>ArrowRight</code></td><td>open, focus on branch（dir=rtl 时改由 ArrowLeft 承担）</td><td>收起的分支就地展开；已展开则把焦点移到首个子节点；叶子上什么都不做且不吞键</td></tr><tr><td><code>ArrowLeft</code></td><td>open, focus in content（dir=rtl 时改由 ArrowRight 承担）</td><td>展开的分支就地收起；收起的分支与叶子则把焦点移到父节点；根层的行什么都不做</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>open, 焦点节点未禁用</td><td>选中焦点节点：单选替换并收起浮层、焦点归还 trigger；多选切换且浮层不收起</td></tr><tr><td><code>*</code></td><td>open, focus in content</td><td>展开与焦点行同一父级的全部分支（已展开与禁用的不动）；同级没有可展开的分支时不吞这个键</td></tr><tr><td><code>单个可打印字符</code></td><td>open, focus in content</td><td>连打检索在可见行上按 label 首字母搬焦点，不改选中值，也不展开任何分支</td></tr><tr><td><code>Escape</code></td><td>open</td><td>收起浮层并把焦点归还 trigger，选中值与展开集合都不变</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>收起浮层，焦点不归还 trigger，按 Tab 序列自然离开</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>tree</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;tree&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id <code>value-text</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>role</code></td><td>&#39;combobox&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>aria-label</code></td><td>props.translations.clearTrigger</td></tr><tr><td><code>tree</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>tree</code></td><td><code>aria-label</code></td><td>props.translations.tree</td></tr><tr><td><code>tree</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id <code>value-text</code> 部件的 id</td></tr><tr><td><code>tree</code></td><td><code>aria-multiselectable</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>tree</code></td><td><code>role</code></td><td>&#39;tree&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-label</code></td><td>metaOf(node.value)?.label</td></tr><tr><td><code>branch-trigger</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tree-select.css</code> 按部件选择：<code>[data-scope=&quot;tree-select&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-placeholder</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>value-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>value-text</code></td><td><code>data-placeholder</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-clearable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>positioner</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>tree</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tree</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tree-select-action-bg</code> · <code>--xh-tree-select-action-bg-active</code> · <code>--xh-tree-select-action-bg-hover</code> · <code>--xh-tree-select-action-fg</code> · <code>--xh-tree-select-action-fg-hover</code> · <code>--xh-tree-select-action-font-size</code> · <code>--xh-tree-select-action-radius</code> · <code>--xh-tree-select-action-size</code> · <code>--xh-tree-select-branch-indicator-fg</code> · <code>--xh-tree-select-content-bg</code> · <code>--xh-tree-select-content-border</code> · <code>--xh-tree-select-content-fg</code> · <code>--xh-tree-select-content-max-h</code> · <code>--xh-tree-select-content-max-w</code> · <code>--xh-tree-select-content-min-w</code> · <code>--xh-tree-select-content-px</code> · <code>--xh-tree-select-content-py</code> · <code>--xh-tree-select-content-radius</code> · <code>--xh-tree-select-content-shadow</code> · <code>--xh-tree-select-gap</code> · <code>--xh-tree-select-icon-size</code> · <code>--xh-tree-select-indent</code> · <code>--xh-tree-select-indicator-fg</code> · <code>--xh-tree-select-indicator-size</code> · <code>--xh-tree-select-item-indicator-fg</code> · <code>--xh-tree-select-label-fg</code> · <code>--xh-tree-select-label-font-size</code> · <code>--xh-tree-select-label-font-weight</code> · <code>--xh-tree-select-layer</code> · <code>--xh-tree-select-placeholder-fg</code> · <code>--xh-tree-select-row-bg-hover</code> · <code>--xh-tree-select-row-fg</code> · <code>--xh-tree-select-row-fg-selected</code> · <code>--xh-tree-select-row-font-size</code> · <code>--xh-tree-select-row-gap</code> · <code>--xh-tree-select-row-leading</code> · <code>--xh-tree-select-row-px</code> · <code>--xh-tree-select-row-py</code> · <code>--xh-tree-select-row-radius</code> · <code>--xh-tree-select-row-selected-font-weight</code> · <code>--xh-tree-select-trigger-bg</code> · <code>--xh-tree-select-trigger-bg-disabled</code> · <code>--xh-tree-select-trigger-bg-readonly</code> · <code>--xh-tree-select-trigger-border</code> · <code>--xh-tree-select-trigger-border-focus</code> · <code>--xh-tree-select-trigger-border-hover</code> · <code>--xh-tree-select-trigger-border-invalid</code> · <code>--xh-tree-select-trigger-fg</code> · <code>--xh-tree-select-trigger-font-size</code> · <code>--xh-tree-select-trigger-gap</code> · <code>--xh-tree-select-trigger-h</code> · <code>--xh-tree-select-trigger-min-w</code> · <code>--xh-tree-select-trigger-px</code> · <code>--xh-tree-select-trigger-radius</code> · <code>--xh-tree-select-value-leading</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>大树一定要开浮层内过滤，逐级展开找一个节点非常慢。</li><li>明确&quot;只能选叶子&quot;还是&quot;分支也能选&quot;，并在界面上让分支看起来点得动或点不动。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>一次把整棵大树塞进浮层：首屏就卡住。</li><li>勾选策略与后端理解不一致。</li></ul>',48))])}const S=n(h,[["render",g]]);export{P as __pageData,S as default};
